from collections import deque
def comps(blk):
    H,W=len(blk),len(blk[0]); seen=set(); sizes=[]
    for r in range(H):
        for c in range(W):
            if blk[r][c] and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); s=0
                while q:
                    a,b=q.popleft(); s+=1
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and blk[x][y] and (x,y) not in seen:
                            seen.add((x,y)); q.append((x,y))
                sizes.append(s)
    return sizes
