def solve(grid, mode, tr, tie):
    blocks,bcol=get_blocks(grid)
    H=len(grid)
    n=len(blocks)
    cnt={bc:sum(1 for blk in blocks for row in blk for x in row if x==bc) for bc in bcol}
    order=sorted([i for i in range(n)], key=lambda i:(cnt[bcol[i]], tie*i))
    out=[[0]*n for _ in range(H)]
    for r in range(H):
        for ci in range(n):
            cand=[i for i in order if blocks[i][r][ci]]
            if cand:
                i=cand[0] if mode=='min' else cand[-1]
                if tr: out[ci][r]=bcol[i]
                else: out[r][ci]=bcol[i]
    return out
